#!/usr/bin/env python3
"""Regenerate readable measurement tables from retained raw JSON samples."""
import json
from pathlib import Path


def timing(s):
    return f"{s['median_ms']:.2f} [{s['min_ms']:.2f}, {s['max_ms']:.2f}]"


def main():
    root = Path(__file__).resolve().parents[2] / "docs/architecture/registry-index-assessment"
    evidence = root / "evidence"
    bench = json.loads((evidence / "benchmark.json").read_text())
    native = json.loads((evidence / "native.json").read_text())
    transport = json.loads((evidence / "transport.json").read_text())
    lines = ["# Measurements", "", "Generated by `scripts/registry-index-assessment/summarize.py`.", "",
             "MB = 1,000,000 bytes. Times are median [min, max] in milliseconds; samples remain in evidence JSON.",
             "Python model and native Rust measurements are different experiments, not interchangeable.", "",
             "## Snapshot storage", "", "| Layout | Packages x versions | Extra bytes/version | Logical MB | Allocated MB | tar.gz MB | Packed snapshot .git MB |",
             "|---|---:|---:|---:|---:|---:|---:|"]
    for s in bench["snapshots"]:
        d = s["disk"]
        lines.append(f"| {s['format']} | {s['packages']} x {s['versions_per_package']} | {s['extra_bytes']} | {d['logical_bytes']/1e6:.3f} | {d['allocated_bytes']/1e6:.3f} | {s['tar_gzip_bytes']/1e6:.3f} | {s['git_snapshot']['git_bytes']/1e6:.3f} |")
    lines += ["", "## Python metadata operations", "", "| Layout | Packages x versions | Extra | Exact warm | Exact fresh process | Latest selection | Publish | Yank |", "|---|---:|---:|---|---|---|---|---|"]
    for s in bench["snapshots"]:
        lines.append(f"| {s['format']} | {s['packages']} x {s['versions_per_package']} | {s['extra_bytes']} | " + " | ".join(timing(s[k]) for k in ("exact_warm", "exact_process_cold", "latest_proxy", "publish_metadata", "yank_metadata")) + " |")
    lines += ["", "Fresh process includes Python startup; OS page cache is not flushed. Latest is a candidate algorithm, not today's exact-only fetch resolver.", "",
              "Yank samples repeatedly write the same flag to isolate rewrite cost; production correctly rejects a repeated yank. Publish samples add distinct versions. Metadata operations exclude Git commits and uploads.", "",
              "## Git timings", "", "| Layout | Packages x versions | Extra | Full clone + checkout | Shallow clone + checkout | Incremental fetch + reset |", "|---|---:|---:|---|---|---|"]
    for s in bench["snapshots"]:
        lines.append(f"| {s['format']} | {s['packages']} x {s['versions_per_package']} | {s['extra_bytes']} | " + " | ".join(timing(s[k]) for k in ("clone_full", "clone_shallow", "incremental_fetch_reset")) + " |")
    lines += ["", "Clone uses file:// and fresh destination directories; this measures local upload-pack, object handling and checkout, not Internet latency. Snapshot clone source has a baseline commit and one mutation commit.", "",
              "## Actual received Git PACK bytes", "", "| Layout | Baseline versions | Full clone bytes (samples) | Shallow clone bytes (samples) | One-release fetch bytes (samples) |", "|---|---:|---|---|---|"]
    for s in transport["scenarios"]:
        lines.append(f"| {s['format']} | {s['versions']} | {s['full_clone_pack_bytes']} | {s['shallow_clone_pack_bytes']} | {s['one_release_fetch_pack_bytes']} |")
    lines += ["", "PACK counts exclude protocol framing and SSH/TLS overhead. Do not treat benchmark.json incremental_object_bytes as network traffic: received deltas can become full loose blobs on disk.", "",
              "## One release per commit", "", "| Layout | Releases | .git before GC MB | .git after GC MB | Publish + commit | Full clone | Shallow clone |", "|---|---:|---:|---:|---|---|---|"]
    for h in bench["histories"]:
        lines.append(f"| {h['format']} | {h['sequential_releases']} | {h['before_gc']['git_bytes']/1e6:.3f} | {h['after_gc']['git_bytes']/1e6:.3f} | {timing(h['per_release_ms'])} | {timing(h['full_clone'])} | {timing(h['shallow_clone'])} |")
    lines += ["", "History has an initial empty package commit plus 1,000 release commits. Auto-GC is disabled during publication, then explicit default git gc runs. No 10,000- or 100,000-release history extrapolation is claimed.", "",
              "## Native production code", "", "| Versions | Rust resolver | Peak RSS MB (samples) | CLI local publish | CLI yank via file remote |", "|---:|---|---|---|---|"]
    for s in native["scenarios"]:
        rss = [round(v / 1e6, 2) if v is not None else None for v in s["max_rss_bytes_macos"]]
        lines.append(f"| {s['versions']} | {timing(s['resolver_in_process'])} | {rss} | {timing(s['cli_publish_local'])} | {timing(s['cli_yank_remote_file'])} |")
    lines += ["", "Resolver imports production modules unchanged into a release-optimized temporary crate: 5 processes x 5 lookups. The CLI binary is debug; publication includes metadata update and commit, excludes external artifact upload. Yank includes clone/pull and push; first sample clones, later samples reuse the clone. Peak RSS covers the resolver process, not full CLI fetch.", "",
              "## Hypothetical HTTP body sizes", "", "| Layout | Packages x versions | Extra | Exact requests | Exact gzip bytes | Discovery requests | Discovery gzip bytes |", "|---|---:|---:|---:|---:|---:|---:|"]
    for s in bench["snapshots"]:
        h = s["hypothetical_http"]
        lines.append(f"| {s['format']} | {s['packages']} x {s['versions_per_package']} | {s['extra_bytes']} | {h['exact_requests']} | {h['exact_gzip_body_bytes']} | {h['discovery_requests']} | {h['discovery_gzip_body_bytes']} |")
    lines += ["", "These are compressed bodies after mutation samples, not HTTP benchmarks. Exact split lookup bypasses the catalog and reads package metadata plus one version. Discovery additionally reads versions.json; more requests may be needed if highest candidates are yanked. No ETag, CDN cache hit rate, auth, pagination or network latency is modeled.", ""]
    (root / "MEASUREMENTS.md").write_text("\n".join(lines))


if __name__ == "__main__":
    main()
